# W-M1 project schema and validation
sb=$(layerfs sandbox create | jq -r .sandbox)
ws=$(layerfs workspace mount "$sb" work.2 | jq -r .ws)
IFS= read -r -d '' cmd <<'CMD'
timeout 110 bash -c 'node --input-type=module <<'\''NODE'\''
import fs from '\''node:fs'\'';
const files = JSON.parse(Buffer.from('\'''\'', '\''base64'\'').toString());
for (const [name, content] of Object.entries(files)) {
  fs.mkdirSync(name.slice(0, name.lastIndexOf('\''/'\'')), { recursive: true });
  fs.writeFileSync(name, content);
}
console.log(JSON.stringify({ written: Object.keys(files) }));
NODE
'
