IFS= read -r -d '' cmd <<'CMD'
timeout 110 bash -c 'npm run prepare-tests && npm run build && CREW_DATA_DIR=./data/w1-proof node --input-type=module - <<'"'"'W1_PROOF'"'"'
import assert from '"'"'node:assert/strict'"'"';
import {startServer,createContext,persist,load} from '"'"'./scripts/acceptance-runtime.mjs'"'"';
import * as issues from '"'"'./scripts/checks/work-issues.mjs'"'"';
let server;const checks=[];let ids={};
try{
  server=await startServer();let ctx=createContext(server.url,ids,checks);
  for(const [actor,name] of [['"'"'owner'"'"','"'"'Proof Owner'"'"'],['"'"'member'"'"','"'"'Proof Member'"'"'],['"'"'guest'"'"','"'"'Proof Guest'"'"']])await ctx.signup(actor,{name,email:actor+'"'"'-'"'"'+Date.now()+'"'"'@proof.test'"'"',password:'"'"'proof acceptance password'"'"'});
  ids.orgId=(await ctx.api('"'"'POST'"'"','"'"'/orgs'"'"',{name:'"'"'Issue proof'"'"'})).organization.id;
  await ctx.api('"'"'POST'"'"','"'"'/orgs/'"'"'+ids.orgId+'"'"'/members'"'"',{userId:ctx.clients.member.user.id,role:'"'"'member'"'"'});
  ids.projectId=(await ctx.api('"'"'POST'"'"','"'"'/orgs/'"'"'+ids.orgId+'"'"'/projects'"'"',{key:'"'"'PROOF'"'"',name:'"'"'Issue acceptance proof'"'"'})).project.id;
  await issues.smoke(ctx);await persist('"'"'issue-proof-state.json'"'"',ids);
