CMD
layerfs workspace exec "$ws" "$cmd" -m '015 W-M3 actual HTTP CLI smoke and clean process restart proof' --stream
layerfs workspace commit "$ws" -m 'W1 015 W-M3 actual HTTP CLI smoke and clean process restart proof (exit 0)'
layerfs workspace unmount "$ws"
layerfs sandbox close "$sb"

# W-07: final owned source hash ceiling and process custody after Markdown scopes
sb=$(layerfs sandbox create | jq -r .sandbox)
ws=$(layerfs workspace mount "$sb" work.5 | jq -r .ws)
IFS= read -r -d '' cmd <<'CMD'
timeout 110 bash -c 'node --input-type=module <<'"'"'JS'"'"'
import fs from '"'"'node:fs/promises'"'"';
import crypto from '"'"'node:crypto'"'"';
const root='"'"'packages'"'"';
async function walk(path){let out=[];for(const row of await fs.readdir(path,{withFileTypes:true})){const name=path+'"'"'/'"'"'+row.name;if(row.isDirectory())out.push(...await walk(name));else if(row.isFile()&&/\.(?:[cm]?js|jsx)$/.test(name)&&/^packages\/[^/]+\/(?:src\/|bin\/)/.test(name))out.push(name);}return out;}
const rows=[];for(const path of await walk(root)){const text=await fs.readFile(path,'"'"'utf8'"'"');rows.push({path,physicalLines:text.split('"'"'\n'"'"').length-(text.endsWith('"'"'\n'"'"')?1:0)});}
rows.sort((a,b)=>b.physicalLines-a.physicalLines);
const hash=crypto.createHash('"'"'sha256'"'"').update(await fs.readFile('"'"'scripts/count-loc.mjs'"'"')).digest('"'"'hex'"'"');
const expected='"'"'f73b6acb7d073e90631936ad62be8705a9c2a2f93c7e2097e7ca4f5c062f12ab'"'"';
const violations=rows.filter(row=>row.physicalLines>999);
const children=[];
for(const name of await fs.readdir('"'"'/proc'"'"')){
 if(!/^\d+$/.test(name)||Number(name)===process.pid)continue;
 try{const stat=await fs.readFile('"'"'/proc/'"'"'+name+'"'"'/stat'"'"','"'"'utf8'"'"');const found=stat.match(/^(\d+) \((.*?)\) ([A-Z]) (\d+)/);if(found&&['"'"'node'"'"','"'"'python3'"'"','"'"'chromium'"'"','"'"'chrome_crashpad'"'"','"'"'chromedriver'"'"','"'"'esbuild'"'"'].includes(found[2]))children.push({pid:Number(found[1]),command:found[2],state:found[3],ppid:Number(found[4])});}catch(error){if(error.code!=='"'"'ENOENT'"'"'&&error.code!=='"'"'ESRCH'"'"')throw error;}
}
const liveChildren=children.filter(row=>row.state!=='"'"'Z'"'"');
console.log(JSON.stringify({liveChildren,deadZ:children.filter(row=>row.state==='"'"'Z'"'"'),ok:!liveChildren.length},null,2));
if(liveChildren.length)process.exitCode=1;
console.log(JSON.stringify({counterSha256:hash,frozenMatch:hash===expected,files:rows.length,violations,largestPhysical:rows.slice(0,10),ok:hash===expected&&!violations.length},null,2));
if(hash!==expected||violations.length)process.exitCode=1;
JS'
CMD
layerfs workspace exec "$ws" "$cmd" -m 'final owned source hash ceiling and process custody after Markdown scopes' --stream
layerfs workspace commit "$ws" -m 'W1b 167 W-07: final owned source hash ceiling and process custody after Markdown scopes (exit 0)'
layerfs workspace unmount "$ws"
layerfs sandbox close "$sb"

# I-09: final source counter physical and live-process census
sb=$(layerfs sandbox create | jq -r .sandbox)
ws=$(layerfs workspace mount "$sb" insight.4 | jq -r .ws)
IFS= read -r -d '' cmd <<'CMD'
timeout 110 bash -c 'node scripts/count-loc.mjs && sha256sum scripts/count-loc.mjs && node --input-type=module <<'"'"'NODE'"'"'
import {readdirSync,readFileSync} from '"'"'node:fs'"'"';
import {execFileSync} from '"'"'node:child_process'"'"';
const files=[];
function scan(directory){for(const entry of readdirSync(directory,{withFileTypes:true})){const path=directory+'"'"'/'"'"'+entry.name;if(entry.isDirectory())scan(path);else if(entry.isFile()&&/\.(js|jsx|mjs|cjs)$/.test(path)){const text=readFileSync(path,'"'"'utf8'"'"');files.push({path,physical:text.split('"'"'\n'"'"').length-(text.endsWith('"'"'\n'"'"')?1:0)});}}}
for(const name of readdirSync('"'"'packages'"'"')){scan('"'"'packages/'"'"'+name+'"'"'/src'"'"');if(name==='"'"'cli'"'"')scan('"'"'packages/cli/bin'"'"');}
files.sort((a,b)=>b.physical-a.physical||a.path.localeCompare(b.path));
console.log('"'"'PHYSICAL_CENSUS '"'"'+JSON.stringify({files:files.length,max:files[0].physical,over999:files.filter(f=>f.physical>999),largest:files.slice(0,12)}));
const rows=execFileSync('"'"'ps'"'"',['"'"'-eo'"'"','"'"'pid,ppid,stat,comm,args'"'"'],{encoding:'"'"'utf8'"'"'}).trim().split('"'"'\n'"'"').slice(1).map(line=>{const match=line.trim().match(/^(\d+)\s+(\d+)\s+(\S+)\s+(\S+)\s*(.*)$/);return match?{pid:Number(match[1]),ppid:Number(match[2]),stat:match[3],comm:match[4],args:match[5]}:null;}).filter(Boolean);
const owned=rows.filter(r=>r.pid!==process.pid&&/^(chrom|chrome|esbuild|node|python)/.test(r.comm));
const live=owned.filter(r=>!r.stat.startsWith('"'"'Z'"'"')),defunct=owned.filter(r=>r.stat.startsWith('"'"'Z'"'"'));
console.log('"'"'PROCESS_CENSUS '"'"'+JSON.stringify({live,defunct}));
if(files.some(f=>f.physical>999)||live.length)process.exitCode=1;

NODE'
CMD
layerfs workspace exec "$ws" "$cmd" -m 'final source counter physical and live-process census' --stream
layerfs workspace commit "$ws" -m 'I2c I-09: final source counter physical and live-process census (exit 0)'
layerfs workspace unmount "$ws"
layerfs sandbox close "$sb"
